schema_ddl:
CREATE TABLE fatture (
    id INT PRIMARY KEY,
    data_fattura DATE NOT NULL,
    importo NUMERIC(10,2) NOT NULL CHECK (importo > 0),
    descrizione TEXT
);

CREATE TABLE pagamenti (
    id_fattura INT PRIMARY KEY REFERENCES fatture(id),
    data_pagamento DATE NOT NULL,
    metodo_pagamento TEXT NOT NULL CHECK (metodo_pagamento IN ('contanti', 'assegno', 'bonifico')),
    note TEXT
);
